-- Migration: Year 3 - Psychiatry - Psychotic Disorders MCQ Bank (1-320)
-- Based on Kaplan & Sadock's Synopsis 12th Ed, First Aid for the Psychiatry Clerkship 5th Ed, and MGH Pocket Psychiatry
-- Date: 2026-04-30

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'psychotic-disorders' LIMIT 1;

    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Schizophrenia Basics & Diagnosis (1-60)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the minimum duration of continuous signs of disturbance required for a diagnosis of Schizophrenia?', '["1 month", "3 months", "6 months", "1 year"]', 2, 'Must include at least 1 month of active phase symptoms. (DSM-5)'),
    (v_topic_id, '2: How many active-phase symptoms are required for Schizophrenia (Criterion A)?', '["At least 1", "At least 2", "At least 3", "All 5"]', 1, 'Must have 2 or more, and at least one must be delusions, hallucinations, or disorganized speech. (DSM-5)'),
    (v_topic_id, '3: Which of the following is a "positive" symptom of Schizophrenia?', '["Avolition", "Alogia", "Hallucinations", "Anhedonia"]', 2, 'Positive symptoms add to normal experience (delusions, hallucinations, disorganized behavior). (Kaplan & Sadock)'),
    (v_topic_id, '4: Which of the following is a "negative" symptom of Schizophrenia?', '["Delusions", "Disorganized speech", "Affective flattening", "Agitation"]', 2, 'Negative symptoms subtract from normal function (affective flattening, avolition, alogia, anhedonia, asociality). (First Aid)'),
    (v_topic_id, '5: What is the most common type of hallucination in Schizophrenia?', '["Visual", "Auditory", "Olfactory", "Tactile"]', 1, 'Auditory hallucinations (often voices conversing or commanding) are hallmark. (MGH Pocket)'),
    (v_topic_id, '6: "Alogia" refers to:', '["Lack of energy", "Lack of speech (poverty of speech)", "Lack of movement", "Lack of pleasure"]', 1, 'Brief, empty replies. (Kaplan & Sadock)'),
    (v_topic_id, '7: "Avolition" refers to:', '["Lack of speech", "Inability to initiate and persist in goal-directed activities", "Inability to feel pleasure", "Lack of emotion"]', 1, 'Patient may sit for hours doing nothing. (First Aid)'),
    (v_topic_id, '8: What is a "bizarre" delusion?', '["A belief that the FBI is tracking them", "A belief that their spouse is cheating", "A belief that aliens removed their brain through their nose without leaving a scar", "A belief that they are Jesus"]', 2, 'Physically impossible and implausible to one''s culture. (DSM-5)'),
    (v_topic_id, '9: "Thought insertion" is a specific delusion where the patient believes:', '["Thoughts are being broadcast out loud", "Outside thoughts are being put into their mind", "Their thoughts are being stolen", "They can read minds"]', 1, 'Classic Schneiderian first-rank symptom. (Kaplan & Sadock)'),
    (v_topic_id, '10: "Thought broadcasting" is the delusion that:', '["Others can hear the patient''s thoughts", "The TV is speaking to them", "They are on a radio show", "They have no thoughts"]', 0, 'Another first-rank symptom. (First Aid)'),
    (v_topic_id, '11: "Ideas of reference" (or delusions of reference) involve:', '["Believing one is a famous historical figure", "Believing neutral events (like a TV anchor) hold special, personal meaning directed at them", "Believing one is dead", "Believing one is infected"]', 1, 'Very common in early psychosis. (MGH Pocket)'),
    (v_topic_id, '12: What is the peak age of onset for Schizophrenia in men?', '["10-15 years", "15-25 years", "25-35 years", "40-50 years"]', 1, 'Onset is typically earlier in men than women. (Kaplan & Sadock)'),
    (v_topic_id, '13: What is the peak age of onset for Schizophrenia in women?', '["15-25 years", "25-35 years", "40-50 years", "50+ years"]', 1, 'Women have a later onset and a bimodal distribution (second peak after 40). (First Aid)'),
    (v_topic_id, '14: What is the lifetime prevalence of Schizophrenia worldwide?', '["0.1%", "1%", "5%", "10%"]', 1, 'Roughly 1% across all cultures. (Kaplan & Sadock)'),
    (v_topic_id, '15: Schizophrenia is more common in which demographic group (though often thought to be an artifact of downward drift)?', '["High socioeconomic status", "Low socioeconomic status", "Middle class", "No difference"]', 1, 'The "downward drift" hypothesis suggests the illness impairs the ability to maintain social status. (First Aid)'),
    (v_topic_id, '16: The risk of Schizophrenia if one identical (monozygotic) twin is affected is roughly:', '["10%", "25%", "50%", "100%"]', 2, 'About 40-50%. Indicates a strong genetic component but also environmental factors. (Kaplan & Sadock)'),
    (v_topic_id, '17: The risk of Schizophrenia if a first-degree relative (parent or sibling) is affected is roughly:', '["1%", "10%", "25%", "50%"]', 1, 'Approximately 10-12%. (MGH Pocket)'),
    (v_topic_id, '18: Which neurotransmitter hypothesis is central to Schizophrenia''s positive symptoms?', '["Serotonin excess", "Dopamine excess in the mesolimbic pathway", "GABA deficiency", "Glutamate excess"]', 1, 'The classic dopamine hypothesis. (First Aid)'),
    (v_topic_id, '19: The negative symptoms of Schizophrenia are thought to be related to:', '["Dopamine excess in the mesolimbic pathway", "Dopamine deficit in the mesocortical pathway", "Serotonin deficit", "Histamine excess"]', 1, 'Explains why typical antipsychotics (D2 blockers) don''t help (and can worsen) negative symptoms. (Kaplan & Sadock)'),
    (v_topic_id, '20: Which recreational drug is a known NMDA receptor antagonist that can cause a syndrome indistinguishable from Schizophrenia (positive + negative symptoms)?', '["Cocaine", "PCP (Phencyclidine)", "Heroin", "Cannabis"]', 1, 'Supports the Glutamate hypothesis of schizophrenia. (MGH Pocket)'),
    (v_topic_id, '21: Which neuroanatomical finding is most consistently seen on CT/MRI in Schizophrenia?', '["Shrunken cerebellum", "Enlarged lateral and third ventricles (due to cortical atrophy)", "Enlarged hippocampus", "Atrophy of the occipital lobe"]', 1, 'Reflects loss of cortical tissue. (First Aid)'),
    (v_topic_id, '22: Which complication during pregnancy/birth is epidemiologically linked to a higher risk of Schizophrenia?', '["Maternal influenza infection during the second trimester", "C-section delivery", "Gestational diabetes", "Breech presentation"]', 0, 'Also winter/spring birth dates (season of birth effect). (Kaplan & Sadock)'),
    (v_topic_id, '23: The "prodromal" phase of Schizophrenia often looks similar to which personality disorder?', '["Borderline PD", "Schizotypal or Schizoid PD", "Antisocial PD", "Histrionic PD"]', 1, 'Social withdrawal, odd beliefs, blunted affect before full psychosis hits. (First Aid)'),
    (v_topic_id, '24: The "active" phase of Schizophrenia is characterized by:', '["Avolition only", "Prominent positive symptoms (hallucinations, delusions)", "Return to baseline", "Depression"]', 1, 'The psychotic break. (MGH Pocket)'),
    (v_topic_id, '25: The "residual" phase of Schizophrenia is characterized by:', '["Active hallucinations", "Mild or subthreshold positive symptoms and prominent negative symptoms", "Complete remission", "Mania"]', 1, 'Often resembles the prodrome. (Kaplan & Sadock)'),
    (v_topic_id, '26: Which symptom is generally the most refractory to antipsychotic treatment?', '["Hallucinations", "Delusions", "Negative symptoms (e.g., avolition) and Cognitive deficits", "Agitation"]', 2, 'Current drugs are poor at treating the negative/cognitive domains. (First Aid)'),
    (v_topic_id, '27: "Disorganized speech" in Schizophrenia can manifest as "tangentiality," which means:', '["Wandering off the topic and never returning to the original point", "Providing excessive unnecessary detail but eventually answering the question", "Repeating words", "Making up words"]', 0, 'Circumstantiality eventually returns to the point; tangentiality does not. (MGH Pocket)'),
    (v_topic_id, '28: "Loose associations" (Derailment) refers to:', '["Shifting topics with no logical connection", "Speech based on sounds (rhyming)", "Inventing words", "Stopping mid-sentence"]', 0, 'The ideas slip off track onto completely unrelated topics. (Kaplan & Sadock)'),
    (v_topic_id, '29: "Clang associations" are characterized by:', '["Logical arguments", "Choosing words based on sound, often rhyming or punning", "Muteness", "Repeating the interviewer"]', 1, '"I am the cat, who sat on the mat, wearing a hat." (First Aid)'),
    (v_topic_id, '30: "Neologisms" are:', '["Old words used correctly", "Newly invented words or phrases that only have meaning to the patient", "Foreign languages", "Echolalia"]', 1, 'A form of disorganized speech. (Kaplan & Sadock)'),
    (v_topic_id, '31: "Thought blocking" refers to:', '["Refusing to answer questions", "A sudden interruption in speech/thought process mid-sentence", "Speaking too fast", "Forgetting a name"]', 1, 'The patient may feel their thought was "taken out of their head." (MGH Pocket)'),
    (v_topic_id, '32: "Word salad" (Incoherence) is:', '["A severe form of disorganized speech where words are thrown together without any syntactic structure", "Speaking very fast", "Stuttering", "None"]', 0, 'Highest level of disorganization. (First Aid)'),
    (v_topic_id, '33: What is the most common comorbid substance use disorder in Schizophrenia?', '["Cocaine use disorder", "Nicotine use disorder (Tobacco)", "Heroin use disorder", "Alcohol use disorder"]', 1, 'Up to 90% of patients with schizophrenia smoke. (Kaplan & Sadock)'),
    (v_topic_id, '34: Why do patients with Schizophrenia heavily smoke tobacco?', '["It looks cool", "Nicotine may temporarily improve some cognitive and sensory gating deficits (self-medication)", "It reduces hallucinations", "It prevents EPS"]', 1, 'Nicotine stimulates alpha-7 nicotinic receptors. (First Aid)'),
    (v_topic_id, '35: What is the risk of suicide in Schizophrenia?', '["<1%", "5-6% (approx 10% historically)", "25%", "50%"]', 1, 'Significantly elevated compared to the general population. (MGH Pocket)'),
    (v_topic_id, '36: Suicide in Schizophrenia most often occurs during which period?', '["During active psychosis", "During the post-psychotic depression phase (often when they realize the chronicity of the illness)", "Before onset", "Never"]', 1, 'High insight is ironically a risk factor for suicide. (Kaplan & Sadock)'),
    (v_topic_id, '37: Which type of hallucinations should ALWAYS prompt a thorough medical workup (as they are less common in primary Schizophrenia)?', '["Auditory", "Visual, Olfactory, or Tactile", "Second-person auditory", "Command auditory"]', 1, 'Visual/Olfactory suggest medical/neurological causes (e.g., temporal lobe epilepsy, delirium). (First Aid)'),
    (v_topic_id, '38: "Erotomanic" delusions involve the belief that:', '["One is pregnant", "Another person, usually of higher status, is in love with them", "One has a foul odor", "One is rotting"]', 1, 'Common in Delusional Disorder, but can occur in Schizophrenia. (MGH Pocket)'),
    (v_topic_id, '39: "Somatic" delusions involve the belief that:', '["One is famous", "One has a physical defect, disease, or altered bodily function", "One is dead", "The world is ending"]', 1, 'e.g., "My brain is melting." (Kaplan & Sadock)'),
    (v_topic_id, '40: "Cotard syndrome" (Nihilistic delusion) is the belief that:', '["One is God", "One is dead, does not exist, or has lost their internal organs", "One is being followed", "One''s spouse is replaced by an impostor"]', 1, 'Often seen in severe psychotic depression or schizophrenia. (First Aid)'),
    (v_topic_id, '41: "Capgras syndrome" is the delusion that:', '["One is dead", "A familiar person has been replaced by an identical impostor", "Different people are actually a single person in disguise", "None of the above"]', 1, 'A delusion of misidentification. (Kaplan & Sadock)'),
    (v_topic_id, '42: "Fregoli syndrome" is the delusion that:', '["A familiar person is dead", "Various different strangers are actually a single familiar person in disguise", "One is replaced by an alien", "None"]', 1, 'Another misidentification syndrome. (MGH Pocket)'),
    (v_topic_id, '43: Does DSM-5 still use subtypes of Schizophrenia (e.g., paranoid, disorganized, catatonic)?', '["Yes, always", "No, they were eliminated due to low diagnostic stability and overlapping symptoms", "Only for children", "Only for paranoid"]', 1, 'DSM-5 uses a dimensional approach to symptom severity instead. (DSM-5)'),
    (v_topic_id, '44: Good prognostic factors for Schizophrenia include:', '["Early onset, insidious onset, male gender", "Late onset, abrupt onset, female gender, prominent mood symptoms", "Family history of schizophrenia", "Prominent negative symptoms"]', 1, 'Acute onset and good premorbid functioning predict better outcomes. (First Aid)'),
    (v_topic_id, '45: Poor prognostic factors for Schizophrenia include:', '["Acute onset", "Presence of mood symptoms", "Prominent negative symptoms, poor premorbid function, early insidious onset", "Female gender"]', 2, 'Negative symptoms are very difficult to treat. (Kaplan & Sadock)'),
    (v_topic_id, '46: In Schizophrenia, what is the downward drift hypothesis?', '["Illness causes a drop in socioeconomic status", "Living in poverty causes the illness", "Drugs cause the illness", "None"]', 0, 'Illness impairs occupational function. (MGH Pocket)'),
    (v_topic_id, '47: In Schizophrenia, what is the social causation hypothesis?', '["Illness causes poverty", "Living in poverty/urban stress contributes to the development of the illness", "None", "Both"]', 1, 'An alternative/complementary theory to downward drift. (Kaplan & Sadock)'),
    (v_topic_id, '48: Which eye tracking abnormality is frequently seen in Schizophrenia patients and their relatives?', '["Nystagmus", "Impaired smooth pursuit eye movements", "Strabismus", "Ptosis"]', 1, 'Considered a neurophysiological biomarker. (First Aid)'),
    (v_topic_id, '49: What is "Catatonia"?', '["A type of depression", "A syndrome characterized by marked psychomotor disturbance (decreased, increased, or peculiar motor activity)", "A type of mania", "Normal movement"]', 1, 'Can occur in Schizophrenia, Bipolar, MDD, or medical conditions. (DSM-5)'),
    (v_topic_id, '50: "Waxy flexibility" (Catalepsy) in catatonia means:', '["The patient fights movement", "The patient''s limbs remain in the position they are placed by the examiner", "The patient is completely flaccid", "None"]', 1, 'Classic catatonic sign. (MGH Pocket)'),
    (v_topic_id, '51: "Negativism" in catatonia means:', '["Saying no to everything", "Motiveless resistance to all instructions or maintenance of a rigid posture against attempts to be moved", "Depressed mood", "None"]', 1, 'The patient actively resists. (Kaplan & Sadock)'),
    (v_topic_id, '52: First-line treatment for Catatonia?', '["Haloperidol", "Lorazepam (Benzodiazepines)", "Fluoxetine", "Lithium"]', 1, 'If unresponsive, ECT is highly effective and life-saving. (First Aid)'),
    (v_topic_id, '53: Should antipsychotics be given acutely to treat Catatonia?', '["Yes, they are first line", "No, they can worsen it or precipitate Neuroleptic Malignant Syndrome (NMS)", "Yes, but only atypicals", "Only if depressed"]', 1, 'Avoid antipsychotics until catatonia resolves. (MGH Pocket)'),
    (v_topic_id, '54: Polydipsia (excessive water drinking) is a known issue in chronic Schizophrenia. What is the major medical risk?', '["Hypernatremia", "Water intoxication leading to severe Hyponatremia (seizures, coma)", "Diabetes", "Kidney failure"]', 1, 'Often requires fluid restriction. (Kaplan & Sadock)'),
    (v_topic_id, '55: "Schizophrenia" literally means "split mind." Who coined the term?', '["Sigmund Freud", "Eugen Bleuler", "Emil Kraepelin", "Carl Jung"]', 1, 'Kraepelin called it "dementia praecox". (First Aid)'),
    (v_topic_id, '56: Bleuler''s "4 As" of Schizophrenia include: Affect (blunted), Associations (loose), Autism, and ____.', '["Alogia", "Avolition", "Ambivalence", "Anhedonia"]', 2, 'Ambivalence (conflicting feelings). (Kaplan & Sadock)'),
    (v_topic_id, '57: A patient with Schizophrenia shows no facial expression when discussing the death of a loved one. This is termed:', '["Inappropriate affect", "Flat or blunted affect", "Labile affect", "Anxious affect"]', 1, 'A core negative symptom. (MGH Pocket)'),
    (v_topic_id, '58: A patient with Schizophrenia laughs uncontrollably while discussing a tragic accident. This is termed:', '["Flat affect", "Inappropriate affect", "Euthymia", "Malingering"]', 1, 'Affect does not match the thought content. (First Aid)'),
    (v_topic_id, '59: What is "Illusion" vs "Hallucination"?', '["Illusion is false belief; Hallucination is sensory", "Illusion is a misinterpretation of a REAL external stimulus; Hallucination occurs WITHOUT an external stimulus", "They are the same", "None"]', 1, 'Seeing a shadow and thinking it''s a man = illusion. Seeing a man where there is no shadow = hallucination. (Kaplan & Sadock)'),
    (v_topic_id, '60: Are visual hallucinations more indicative of Schizophrenia or Delirium/Substance intoxication?', '["Schizophrenia", "Delirium/Substance intoxication", "Equally likely", "Neither"]', 1, 'Always suspect a medical cause if hallucinations are visual, tactile, or olfactory. (MGH Pocket)'),

    -- SECTION 2: Other Psychotic Disorders (61-120)
    (v_topic_id, '61: Brief Psychotic Disorder requires psychotic symptoms lasting for:', '["< 1 day", "At least 1 day but < 1 month", "1 to 6 months", "> 6 months"]', 1, 'Followed by full return to premorbid functioning. (DSM-5)'),
    (v_topic_id, '62: Brief Psychotic Disorder is often triggered by:', '["Drugs", "A severe psychosocial stressor (e.g., loss of loved one, trauma)", "Schizophrenia", "Nothing"]', 1, '"Brief reactive psychosis." (First Aid)'),
    (v_topic_id, '63: Schizophreniform Disorder requires psychotic symptoms lasting for:', '["< 1 month", "1 to 6 months", "> 6 months", "> 1 year"]', 1, 'Same symptoms as Schizophrenia, but shorter duration. (DSM-5)'),
    (v_topic_id, '64: What happens if a patient has Schizophreniform disorder and symptoms persist past 6 months?', '["It resolves", "The diagnosis is changed to Schizophrenia", "It becomes Schizoaffective", "It becomes Delusional Disorder"]', 1, 'The 6-month mark is the cutoff. (First Aid)'),
    (v_topic_id, '65: Does Schizophreniform Disorder require impaired social/occupational functioning for diagnosis?', '["Yes", "No", "Only if hospitalized", "Only in men"]', 1, 'Unlike Schizophrenia, functional decline is not strictly required. (DSM-5)'),
    (v_topic_id, '66: Schizoaffective Disorder requires an uninterrupted period of illness during which there is a Major Mood Episode (MDD or Mania) concurrent with:', '["Anxiety", "Criterion A symptoms of Schizophrenia", "Substance abuse", "None"]', 1, 'There is overlap of mood and psychotic symptoms. (Kaplan & Sadock)'),
    (v_topic_id, '67: What is the CRITICAL distinguishing criterion for Schizoaffective Disorder?', '["Mood symptoms are always present", "Delusions or hallucinations for 2 or more weeks IN THE ABSENCE of a major mood episode", "Psychosis only occurs during mood episodes", "None"]', 1, 'This proves the psychosis is primary and independent of the mood. (DSM-5 / First Aid)'),
    (v_topic_id, '68: If a patient ONLY has hallucinations when they are deeply depressed, what is the diagnosis?', '["Schizoaffective Disorder", "Major Depressive Disorder with psychotic features", "Schizophrenia", "Bipolar I"]', 1, 'Psychosis is secondary to the mood episode. (MGH Pocket)'),
    (v_topic_id, '69: Delusional Disorder is characterized by the presence of at least one delusion for a duration of at least:', '["1 week", "1 month", "6 months", "1 year"]', 1, 'Must be at least 1 month. (DSM-5)'),
    (v_topic_id, '70: Which of the following is true regarding Delusional Disorder?', '["Prominent hallucinations are present", "Criterion A for Schizophrenia is NOT met (e.g., no prominent hallucinations or disorganized speech)", "Functioning is markedly impaired", "It is caused by drugs"]', 1, 'Aside from the delusion, functioning is relatively preserved and behavior is not obviously bizarre. (First Aid)'),
    (v_topic_id, '71: In Delusional Disorder, "Persecutory type" means:', '["Belief they have a disease", "Belief they are being conspired against, cheated, spied on, or harassed", "Belief their spouse is unfaithful", "Belief they are famous"]', 1, 'Most common subtype. (Kaplan & Sadock)'),
    (v_topic_id, '72: In Delusional Disorder, "Jealous type" (Othello syndrome) means:', '["Belief they are a god", "Belief their sexual partner is unfaithful based on incorrect inferences from small ''evidence''", "Belief they are loved by a celebrity", "Belief they are infected"]', 1, 'Can lead to violence against the spouse. (MGH Pocket)'),
    (v_topic_id, '73: In Delusional Disorder, "Somatic type" means:', '["Belief they emit a foul odor, are infested with insects, or have internal parasites", "Belief they are pregnant", "Belief they are dead", "All of the above"]', 3, 'Can present to dermatologists (delusions of parasitosis) or surgeons. (First Aid)'),
    (v_topic_id, '74: What is "Folie a deux" (Shared Psychotic Disorder)?', '["Two personalities in one body", "A delusion develops in an individual in the context of a close relationship with another person who already has an established delusion", "Two people who hallucinate", "None"]', 1, 'The dominant person transfers the delusion to the submissive person. (Kaplan & Sadock)'),
    (v_topic_id, '75: Best management for Folie a deux?', '["Give both ECT", "Separate the two individuals; the delusion often resolves in the submissive person", "Give both antipsychotics", "Ignore it"]', 1, 'Separation is key. (MGH Pocket)'),
    (v_topic_id, '76: Postpartum Psychosis typically presents within what timeframe after delivery?', '["1-2 weeks", "6 months", "1 year", "5 years"]', 0, 'Rapid onset, severe symptoms (delusions about the baby, agitation, confusion). (First Aid)'),
    (v_topic_id, '77: Postpartum Psychosis is most strongly associated with an underlying diagnosis of:', '["MDD", "Bipolar Disorder", "Schizophrenia", "Borderline PD"]', 1, 'Considered a presentation of bipolar disorder until proven otherwise. (Kaplan & Sadock)'),
    (v_topic_id, '78: Is Postpartum Psychosis an emergency?', '["No, it resolves on its own", "Yes, due to high risk of suicide and infanticide", "Only if they have a weapon", "None"]', 1, 'Requires immediate hospitalization. (MGH Pocket)'),
    (v_topic_id, '79: Schizotypal Personality Disorder is part of the schizophrenia spectrum. It is characterized by:', '["Frank psychosis", "Eccentric behavior, magical thinking, odd beliefs, and interpersonal deficits WITHOUT full psychosis", "Violent behavior", "Lack of emotions"]', 1, 'Considered premorbid or a mild variant of the schizophrenia spectrum. (First Aid)'),
    (v_topic_id, '80: Substance/Medication-Induced Psychotic Disorder requires that the psychotic symptoms:', '["Developed during or soon after substance intoxication or withdrawal", "Started years before the substance use", "Are unrelated to the substance", "None"]', 0, 'Must rule out primary psychotic disorders. (DSM-5)'),
    (v_topic_id, '81: Which type of hallucinogen is famous for causing "synesthesia" (e.g., seeing sounds)?', '["Cocaine", "LSD", "Alcohol", "Heroin"]', 1, 'Also causes visual illusions and hallucinations. (Kaplan & Sadock)'),
    (v_topic_id, '82: Psychosis caused by long-term, heavy alcohol use often features which specific hallucination?', '["Visual", "Auditory (alcoholic hallucinosis)", "Olfactory", "Tactile"]', 1, 'Occurs in a clear sensorium (unlike delirium tremens). (MGH Pocket)'),
    (v_topic_id, '83: "Formication" is the sensation of bugs crawling under the skin. It is classically associated with intoxication or withdrawal from:', '["Alcohol", "Cocaine or Methamphetamine", "Heroin", "Cannabis"]', 1, '"Cocaine bugs." (First Aid)'),
    (v_topic_id, '84: Psychotic Disorder Due to Another Medical Condition must have evidence that the disturbance is:', '["The direct pathophysiological consequence of another medical condition", "A reaction to the stress of being sick", "Caused by hospital food", "None"]', 0, 'e.g., Psychosis due to brain tumor, SLE, or epilepsy. (DSM-5)'),
    (v_topic_id, '85: Complex partial seizures in the temporal lobe can mimic Schizophrenia, particularly presenting with:', '["Visual hallucinations only", "Olfactory and gustatory hallucinations, along with automatisms", "No hallucinations", "Paralysis"]', 1, 'Often preceded by an "aura" (e.g., smell of burning rubber). (Kaplan & Sadock)'),
    (v_topic_id, '86: A young woman presents with acute psychosis, ovarian teratoma, choreoathetosis, and autonomic instability. Diagnosis?', '["Schizophrenia", "Anti-NMDA receptor encephalitis", "Lupus cerebritis", "Bipolar"]', 1, 'A classic paraneoplastic/autoimmune cause of acute psychosis. (First Aid)'),
    (v_topic_id, '87: Treatment for Anti-NMDA receptor encephalitis?', '["Antipsychotics alone", "Tumor removal and immunosuppression (IVIG, steroids, plasmapheresis)", "ECT", "Lithium"]', 1, 'Must treat the underlying autoimmune process. (MGH Pocket)'),
    (v_topic_id, '88: Acute Intermittent Porphyria (AIP) can present with acute psychosis, peripheral neuropathy, and what physical symptom?', '["Severe abdominal pain", "Chest pain", "Blindness", "Rash"]', 0, 'Autosomal dominant; triggered by drugs, alcohol, fasting. (Kaplan & Sadock)'),
    (v_topic_id, '89: Delirium differs from Schizophrenia primarily by the presence of:', '["Hallucinations", "Waxing and waning level of consciousness and acute onset", "Delusions", "Agitation"]', 1, 'Schizophrenia patients usually have a clear sensorium and stable consciousness. (First Aid)'),
    (v_topic_id, '90: Which test is most useful in differentiating Delirium from Schizophrenia?', '["MRI", "EEG (diffuse slowing in delirium; usually normal in schizophrenia)", "ECG", "CBC"]', 1, 'Delirium shows generalized background slowing on EEG. (MGH Pocket)'),
    (v_topic_id, '91: Childhood-onset Schizophrenia (onset before age 13) has a prognosis that is:', '["Better than adult-onset", "Worse than adult-onset", "Equal to adult-onset", "None"]', 1, 'Usually has a more severe course, prominent negative symptoms, and genetic loading. (Kaplan & Sadock)'),
    (v_topic_id, '92: "Late-onset Schizophrenia" (onset after age 45) is more common in:', '["Men", "Women", "Equal", "Neither"]', 1, 'Often features prominent persecutory delusions and auditory hallucinations, with preserved affect. (First Aid)'),
    (v_topic_id, '93: "Schizoid" Personality Disorder differs from Schizophrenia because Schizoid patients:', '["Have prominent hallucinations", "Prefer to be alone and lack emotional expression, but are NOT psychotic", "Are violent", "None"]', 1, 'No delusions/hallucinations. (DSM-5)'),
    (v_topic_id, '94: A patient believes his nose is hideously deformed, though it appears normal. He requests multiple surgeries. This is a delusion, but the specific DSM-5 diagnosis is:', '["Schizophrenia", "Body Dysmorphic Disorder (with absent insight/delusional beliefs)", "Delusional disorder", "OCD"]', 1, 'Classified under Obsessive-Compulsive and Related Disorders. (First Aid)'),
    (v_topic_id, '95: A patient is convinced they are pregnant, develops abdominal distention, amenorrhea, and morning sickness, but ultrasound is negative. Diagnosis?', '["Pseudocyesis", "Schizophrenia", "Factitious disorder", "Malingering"]', 0, 'A somatic symptom disorder, not a primary psychotic disorder. (Kaplan & Sadock)'),
    (v_topic_id, '96: An elderly patient with hearing loss begins to hear voices and develops paranoia that neighbors are stealing from him. This is an example of psychosis exacerbated by:', '["Dementia", "Sensory deprivation/impairment", "Schizophrenia", "None"]', 1, 'Hearing aids can sometimes improve the symptoms. (MGH Pocket)'),
    (v_topic_id, '97: Delusional Disorder treatment is famously difficult because patients lack insight. First-line somatic treatment is:', '["SSRI", "Antipsychotics (e.g., Aripiprazole, Risperidone), though response is often poor", "Lithium", "ECT"]', 1, 'Therapeutic alliance is crucial; don''t directly challenge the delusion. (Kaplan & Sadock)'),
    (v_topic_id, '98: "Monosymptomatic hypochondriacal psychosis" is an older term for:', '["Schizophrenia", "Delusional Disorder, Somatic Type", "Illness Anxiety Disorder", "Panic Disorder"]', 1, 'e.g., delusion of parasitosis. (First Aid)'),
    (v_topic_id, '99: The classic medication historically used (but less so now) for delusional parasitosis is:', '["Haloperidol", "Pimozide", "Lithium", "Fluoxetine"]', 1, 'Pimozide is a typical antipsychotic, but atypicals are preferred now due to safety. (MGH Pocket)'),
    (v_topic_id, '100: Schizoaffective disorder: Bipolar type vs Depressive type. Which is more common in young adults?', '["Bipolar type", "Depressive type", "Equal", "Neither"]', 0, 'Bipolar type is more common in young adults; Depressive type is more common in older adults. (Kaplan & Sadock)'),
    (v_topic_id, '101: Treatment for Schizoaffective Disorder, Bipolar Type?', '["Antipsychotic + Mood Stabilizer (e.g., Lithium or Valproate)", "Antipsychotic alone", "SSRI alone", "Lithium alone"]', 0, 'Must target both the psychosis and the mood swings. (First Aid)'),
    (v_topic_id, '102: Treatment for Schizoaffective Disorder, Depressive Type?', '["Antipsychotic + Antidepressant", "Mood stabilizer alone", "Antidepressant alone", "ECT only"]', 0, 'Must use antipsychotic for the primary psychosis, plus antidepressant for the mood. (MGH Pocket)'),
    (v_topic_id, '103: A patient has Schizophrenia and severe depression. Does this mean they have Schizoaffective Disorder?', '["Yes", "Not necessarily. If the depression only occurs occasionally or doesn''t meet full MDD criteria, it is Schizophrenia", "No, it''s MDD", "None"]', 1, 'To be Schizoaffective, the mood episodes must be present for the MAJORITY of the total illness duration. (DSM-5)'),
    (v_topic_id, '104: A patient with Schizophrenia presents with acute mutism, negativism, and staring. First step?', '["Lorazepam challenge to assess for catatonia", "Increase antipsychotic dose", "Start SSRI", "Intubate"]', 0, '1-2 mg of IV/IM lorazepam will often temporarily reverse catatonia. (First Aid)'),
    (v_topic_id, '105: "Echopraxia" is:', '["Repeating words", "Repeating the interviewer''s movements", "Refusing to move", "Moving too much"]', 1, 'Seen in catatonia. (Kaplan & Sadock)'),
    (v_topic_id, '106: "Mannerisms" in Schizophrenia are:', '["Normal gestures", "Odd, goal-directed movements that are exaggerated or bizarre", "Random twitches", "None"]', 1, 'e.g., saluting every time they sit down. (MGH Pocket)'),
    (v_topic_id, '107: "Stereotypies" in Schizophrenia are:', '["Odd, goal-directed movements", "Repetitive, non-goal-directed movements (e.g., rocking, pacing)", "Tremors", "None"]', 1, 'Similar to what is seen in Autism. (First Aid)'),
    (v_topic_id, '108: A patient suddenly stops speaking for several seconds, then resumes on a totally different topic. This is:', '["Thought broadcasting", "Thought blocking", "Tangentiality", "Clang associations"]', 1, 'Hallmark of formal thought disorder. (Kaplan & Sadock)'),
    (v_topic_id, '109: What is "Apathy" in Schizophrenia?', '["Feeling sad", "Lack of interest or emotional involvement", "Feeling energetic", "None"]', 1, 'A negative symptom. (First Aid)'),
    (v_topic_id, '110: What is "Asociality" in Schizophrenia?', '["Fear of social situations (Social Anxiety)", "Lack of interest in social interactions", "Antisocial behavior (breaking laws)", "None"]', 1, 'Patients prefer to be alone, distinct from paranoia or anxiety. (MGH Pocket)'),
    (v_topic_id, '111: A patient states "The CIA planted a microchip in my tooth to control my thoughts." What type of delusion is this?', '["Somatic", "Delusion of control / Persecutory", "Grandiose", "Erotomanic"]', 1, 'Classic bizarre delusion of control. (Kaplan & Sadock)'),
    (v_topic_id, '112: A patient hears two voices arguing about him. This is a:', '["First-person auditory hallucination", "Second-person auditory hallucination", "Third-person auditory hallucination", "Visual hallucination"]', 2, 'Third-person (they are talking ABOUT the patient). Highly suggestive of schizophrenia. (First Aid)'),
    (v_topic_id, '113: Which medical condition (an autoimmune disease) is known to cause "Lupus Cerebritis" leading to psychosis?', '["Rheumatoid Arthritis", "Systemic Lupus Erythematosus (SLE)", "Sjogren''s", "Hashimoto''s"]', 1, 'Always consider SLE in a young female with acute psychosis and joint/skin issues. (MGH Pocket)'),
    (v_topic_id, '114: Which infectious disease is classically known as the "Great Imitator" and can cause psychosis in its tertiary stage?', '["HIV", "Syphilis", "Tuberculosis", "Lyme disease"]', 1, 'Neurosyphilis (General Paresis). (First Aid)'),
    (v_topic_id, '115: Untreated HIV can lead to HIV-associated dementia, which can present with:', '["Only memory loss", "Psychosis, apathy, and cognitive decline", "Mania only", "None"]', 1, 'Must check HIV in new-onset psychosis. (Kaplan & Sadock)'),
    (v_topic_id, '116: Huntington''s disease is inherited in an ____ pattern and can present with psychosis/depression before chorea.', '["Autosomal Recessive", "Autosomal Dominant", "X-linked", "Mitochondrial"]', 1, 'CAG repeat expansion. (First Aid)'),
    (v_topic_id, '117: Wilson''s disease is due to impaired ____ metabolism.', '["Iron", "Copper", "Zinc", "Calcium"]', 1, 'Can present with psychiatric symptoms. (MGH Pocket)'),
    (v_topic_id, '118: "Koro" is a culture-bound syndrome seen in Asia characterized by the sudden, intense anxiety that:', '["One is turning into a cannibal", "One''s penis/vulva will recede into the body and cause death", "One is possessed by a fox", "One''s soul has been stolen"]', 1, 'An example of a cultural delusion/anxiety. (Kaplan & Sadock)'),
    (v_topic_id, '119: "Amok" is a culture-bound syndrome (Malaysia) characterized by:', '["Severe depression", "A period of brooding followed by an unprovoked outburst of violent/homicidal behavior", "Fear of the cold", "None"]', 1, '"Running amok." (First Aid)'),
    (v_topic_id, '120: "Taijin kyofusho" is a Japanese culture-bound syndrome characterized by the fear that:', '["One has a disease", "One''s body parts or functions (e.g., odor) are offensive to other people", "One is dead", "None"]', 1, 'Similar to Social Anxiety Disorder, but focuses on offending others. (MGH Pocket)'),

    -- SECTION 3: Antipsychotic Pharmacology (121-180)
    (v_topic_id, '121: First-generation (Typical) antipsychotics work primarily by blocking which receptor?', '["Serotonin 5HT2A", "Dopamine D2", "Histamine H1", "Muscarinic M1"]', 1, 'High affinity for D2 receptors in all dopamine pathways. (Kaplan & Sadock)'),
    (v_topic_id, '122: Which dopamine pathway is hyperactive in Schizophrenia, causing POSITIVE symptoms?', '["Mesocortical", "Mesolimbic", "Nigrostriatal", "Tuberoinfundibular"]', 1, 'Blocking D2 here reduces hallucinations/delusions. (First Aid)'),
    (v_topic_id, '123: Which dopamine pathway is hypoactive in Schizophrenia, causing NEGATIVE symptoms?', '["Mesocortical", "Mesolimbic", "Nigrostriatal", "Tuberoinfundibular"]', 0, 'Blocking D2 here can actually WORSEN negative symptoms. (MGH Pocket)'),
    (v_topic_id, '124: Blocking dopamine in the Nigrostriatal pathway causes:', '["Hyperprolactinemia", "Extrapyramidal Symptoms (EPS)", "Hallucinations", "Weight gain"]', 1, 'Parkinsonism, dystonia, akathisia, TD. (First Aid)'),
    (v_topic_id, '125: Blocking dopamine in the Tuberoinfundibular pathway causes:', '["EPS", "Hyperprolactinemia (galactorrhea, amenorrhea, gynecomastia)", "Dry mouth", "Sedation"]', 1, 'Dopamine normally inhibits prolactin release. (Kaplan & Sadock)'),
    (v_topic_id, '126: High-potency typical antipsychotics include Haloperidol, Fluphenazine, and:', '["Chlorpromazine", "Trifluoperazine", "Thioridazine", "Clozapine"]', 1, '"Try to Fly High" - Trifluoperazine, Fluphenazine, Haloperidol. (First Aid)'),
    (v_topic_id, '127: Low-potency typical antipsychotics include Chlorpromazine and:', '["Haloperidol", "Thioridazine", "Fluphenazine", "Risperidone"]', 1, '"Cheating Thieves are low" - Chlorpromazine, Thioridazine. (First Aid)'),
    (v_topic_id, '128: High-potency typicals have a HIGH risk of ____ and a LOW risk of ____.', '["EPS; Anticholinergic/Antihistamine side effects", "Anticholinergic; EPS", "Weight gain; EPS", "None"]', 0, 'They are very specific for D2. (MGH Pocket)'),
    (v_topic_id, '129: Low-potency typicals have a HIGH risk of ____ and a LOW risk of ____.', '["EPS; Anticholinergic", "Anticholinergic/Antihistamine/Alpha-blockade side effects (sedation, dry mouth, hypotension); EPS", "Weight loss; EPS", "None"]', 1, 'They hit many off-target receptors. (Kaplan & Sadock)'),
    (v_topic_id, '130: Which typical antipsychotic can cause corneal deposits?', '["Haloperidol", "Chlorpromazine", "Thioridazine", "Fluphenazine"]', 1, '"C" for Chlorpromazine and Corneal. (First Aid)'),
    (v_topic_id, '131: Which typical antipsychotic can cause retinal deposits (retinitis pigmentosa)?', '["Haloperidol", "Chlorpromazine", "Thioridazine", "Fluphenazine"]', 2, '"T" for Thioridazine and reTinal. Also highly cardiotoxic (QTc). (MGH Pocket)'),
    (v_topic_id, '132: Acute Dystonia (an EPS) presents as:', '["Restlessness", "Sustained, painful muscle contractions (e.g., torticollis, oculogyric crisis)", "Tremor", "Lip smacking"]', 1, 'Occurs within hours to days of starting the med. (First Aid)'),
    (v_topic_id, '133: Treatment for Acute Dystonia?', '["Stop the drug only", "Anticholinergics (Benztropine) or Antihistamines (Diphenhydramine)", "Beta blockers", "Lithium"]', 1, 'Restores the dopamine-acetylcholine balance in the basal ganglia. (Kaplan & Sadock)'),
    (v_topic_id, '134: Akathisia (an EPS) presents as:', '["Muscle spasm", "Subjective feeling of internal restlessness and inability to sit still", "Tremor", "Rigidity"]', 1, 'Occurs days to weeks after starting. Often misdiagnosed as worsening agitation/anxiety. (MGH Pocket)'),
    (v_topic_id, '135: Treatment for Akathisia?', '["Increase antipsychotic", "Beta blockers (Propranolol), Benzodiazepines, or Benztropine", "Lithium", "SSRI"]', 1, 'Propranolol is often first-line. Decrease antipsychotic dose if possible. (First Aid)'),
    (v_topic_id, '136: Drug-induced Parkinsonism (an EPS) presents as:', '["Restlessness", "Bradykinesia, rigidity, resting tremor, shuffling gait", "Muscle spasm", "Lip smacking"]', 1, 'Occurs weeks to months after starting. (Kaplan & Sadock)'),
    (v_topic_id, '137: Treatment for Drug-induced Parkinsonism?', '["Levodopa", "Anticholinergics (Benztropine) or Amantadine", "Propranolol", "Diphenhydramine"]', 1, 'Do NOT give Levodopa (it will worsen psychosis). (MGH Pocket)'),
    (v_topic_id, '138: Tardive Dyskinesia (TD) presents as:', '["Restlessness", "Choreoathetoid movements, often of the face/mouth (lip smacking, tongue darting)", "Rigidity", "Muscle spasms"]', 1, 'Occurs after months to YEARS of treatment. Can be irreversible. (First Aid)'),
    (v_topic_id, '139: Mechanism of Tardive Dyskinesia?', '["Dopamine excess", "Dopamine D2 receptor upregulation and supersensitivity after chronic blockade", "Serotonin excess", "Acetylcholine deficiency"]', 1, 'This is why increasing the antipsychotic dose temporarily *hides* the TD. (Kaplan & Sadock)'),
    (v_topic_id, '140: Treatment for Tardive Dyskinesia?', '["Benztropine", "Discontinue offending drug; switch to Clozapine/Quetiapine; use VMAT2 inhibitors (Valbenazine, Deutetrabenazine)", "Levodopa", "Propranolol"]', 1, 'Anticholinergics usually WORSEN tardive dyskinesia. (MGH Pocket)'),
    (v_topic_id, '141: Neuroleptic Malignant Syndrome (NMS) presents with the mnemonic "FALTER". What does the "R" stand for?', '["Reflexes (hyper)", "Rigidity (lead-pipe)", "Restlessness", "Rash"]', 1, 'Fever, Autonomic instability, Leukocytosis, Tremor, Elevated CK, Rigidity. (First Aid)'),
    (v_topic_id, '142: NMS vs Serotonin Syndrome: Which features lead-pipe rigidity vs hyperreflexia/clonus?', '["NMS = Rigidity; SS = Hyperreflexia", "NMS = Hyperreflexia; SS = Rigidity", "Both have rigidity", "Neither"]', 0, 'Crucial distinction. (MGH Pocket)'),
    (v_topic_id, '143: First-line treatment for NMS?', '["Cyproheptadine", "Stop the drug, aggressive cooling and hydration, Dantrolene or Bromocriptine", "Benztropine", "Propranolol"]', 1, 'Dantrolene (muscle relaxant) or Bromocriptine (dopamine agonist). (Kaplan & Sadock)'),
    (v_topic_id, '144: Second-generation (Atypical) antipsychotics work by blocking:', '["Dopamine D2 only", "Dopamine D2 AND Serotonin 5HT2A", "Serotonin only", "GABA"]', 1, 'Blocking 5HT2A increases dopamine in the nigrostriatal tract, reducing EPS risk. (First Aid)'),
    (v_topic_id, '145: Compared to typicals, atypicals have a ____ risk of EPS and a ____ risk of metabolic syndrome.', '["Lower; Lower", "Lower; Higher", "Higher; Lower", "Higher; Higher"]', 1, 'The trade-off: less EPS/TD, more weight gain/diabetes. (MGH Pocket)'),
    (v_topic_id, '146: Which atypical antipsychotic is the MOST efficacious for treatment-resistant Schizophrenia?', '["Risperidone", "Olanzapine", "Clozapine", "Aripiprazole"]', 2, 'The gold standard for refractory cases, but reserved due to side effects. (Kaplan & Sadock)'),
    (v_topic_id, '147: Which atypical antipsychotic is the ONLY one FDA approved to reduce suicide risk in Schizophrenia?', '["Quetiapine", "Clozapine", "Lurasidone", "Ziprasidone"]', 1, 'Unique anti-suicidal properties. (First Aid)'),
    (v_topic_id, '148: What is the most feared, potentially fatal side effect of Clozapine?', '["Liver failure", "Agranulocytosis (absolute neutrophil count drops to zero)", "Pulmonary fibrosis", "Renal failure"]', 1, 'Occurs in ~1% of patients. Requires strict blood monitoring (REMS program). (MGH Pocket)'),
    (v_topic_id, '149: How frequently must CBC/ANC be drawn for a patient starting Clozapine?', '["Monthly", "Weekly for the first 6 months, then biweekly for 6 months, then monthly", "Yearly", "Never"]', 1, 'Strict protocol. (Kaplan & Sadock)'),
    (v_topic_id, '150: Aside from agranulocytosis and metabolic syndrome, what are two other major side effects of Clozapine?', '["Seizures (dose-dependent) and Myocarditis", "Blindness and Deafness", "Rash and Alopecia", "None"]', 0, 'Lowers seizure threshold significantly. (First Aid)'),
    (v_topic_id, '151: Which atypical antipsychotic acts most like a "typical" and has the highest risk of EPS and Hyperprolactinemia among the atypicals?', '["Quetiapine", "Risperidone", "Olanzapine", "Aripiprazole"]', 1, 'At doses >6mg, it acts essentially like haloperidol. (MGH Pocket)'),
    (v_topic_id, '152: Which atypical antipsychotics carry the HIGHEST risk of metabolic syndrome (weight gain, dyslipidemia, diabetes)?', '["Aripiprazole and Ziprasidone", "Olanzapine and Clozapine", "Lurasidone and Quetiapine", "Risperidone and Paliperidone"]', 1, 'Patients can gain massive amounts of weight. (Kaplan & Sadock)'),
    (v_topic_id, '153: Which atypical antipsychotic is highly sedating (acts like a strong antihistamine) and is often used for insomnia or bipolar depression?', '["Ziprasidone", "Quetiapine", "Aripiprazole", "Lurasidone"]', 1, 'Nicknamed "Seroquel / Quell-sleep." (First Aid)'),
    (v_topic_id, '154: Which atypical antipsychotic has the HIGHEST risk of QTc prolongation?', '["Aripiprazole", "Ziprasidone", "Olanzapine", "Lurasidone"]', 1, 'Ziprasidone (Geodon) requires baseline and regular ECGs. (MGH Pocket)'),
    (v_topic_id, '155: Which atypical is a partial agonist at D2 receptors?', '["Risperidone", "Aripiprazole", "Quetiapine", "Clozapine"]', 1, 'Aripiprazole (Abilify). Also associated with a unique side effect: increased risk of gambling/compulsive behaviors. (Kaplan & Sadock)'),
    (v_topic_id, '156: Paliperidone is the active metabolite of which drug?', '["Quetiapine", "Risperidone", "Olanzapine", "Aripiprazole"]', 1, 'Available in a long-acting injectable form (Invega Sustenna). (First Aid)'),
    (v_topic_id, '157: Long-acting injectable (LAI) antipsychotics (Depot formulations) are primarily indicated for:', '["First-episode psychosis", "Patients with a history of severe non-adherence", "Treatment-resistant schizophrenia", "Bipolar depression"]', 1, 'Given every 2-4 weeks (or longer) to ensure compliance. (MGH Pocket)'),
    (v_topic_id, '158: Before giving a long-acting injectable, what MUST the physician do?', '["Establish oral tolerability with the pill form first", "Give an anticholinergic", "Give an SSRI", "Do an MRI"]', 0, 'To ensure the patient doesn''t have a severe allergic or EPS reaction to a drug that will stay in their system for a month. (Kaplan & Sadock)'),
    (v_topic_id, '159: Which antipsychotic is available as a sublingual tablet that causes numbness of the tongue and requires no food/water for 10 minutes?', '["Asenapine", "Iloperidone", "Brexpiprazole", "Cariprazine"]', 0, 'Used for schizophrenia and bipolar disorder. (First Aid)'),
    (v_topic_id, '160: Lurasidone is FDA-approved for Schizophrenia and Bipolar Depression. It has a low metabolic profile but MUST be taken with:', '["Empty stomach", "Food (at least 350 calories)", "Milk", "Nothing"]', 1, 'Absorption drops dramatically without food. (MGH Pocket)'),
    (v_topic_id, '161: Cariprazine is unique because it is a partial agonist at both D2 and:', '["5HT2A", "D3 receptors", "Muscarinic", "Histamine"]', 1, 'May have benefit for negative symptoms. (Kaplan & Sadock)'),
    (v_topic_id, '162: What is the FDA "Black Box" warning for ALL antipsychotics in elderly patients with dementia-related psychosis?', '["Increased risk of suicidal thinking", "Increased risk of death (mainly cardiovascular or infectious/pneumonia)", "Increased risk of seizures", "Increased risk of bleeding"]', 1, 'Should only be used if agitation poses a severe risk to self or others. (First Aid)'),
    (v_topic_id, '163: A patient on Haloperidol presents with a stiff, twisted neck looking upward. Diagnosis and treatment?', '["Akathisia; Propranolol", "Acute Dystonia (Torticollis/Oculogyric crisis); IM Benztropine or Diphenhydramine", "NMS; Dantrolene", "TD; Stop drug"]', 1, 'Classic board scenario. (MGH Pocket)'),
    (v_topic_id, '164: A patient on Risperidone is constantly pacing the room, says "I feel like I''m jumping out of my skin", and cannot sit still. Diagnosis and treatment?', '["Agitation; increase Risperidone", "Akathisia; decrease dose or add Propranolol", "Anxiety; add Lorazepam", "TD; add Valbenazine"]', 1, 'Do not increase the antipsychotic! (Kaplan & Sadock)'),
    (v_topic_id, '165: A patient on Fluphenazine has a shuffling gait, masked facies, and a resting tremor. Diagnosis and treatment?', '["Parkinson''s Disease; Levodopa", "Drug-induced Parkinsonism; Benztropine or Amantadine", "Catatonia; Lorazepam", "NMS; Dantrolene"]', 1, 'Common with high-potency typicals. (First Aid)'),
    (v_topic_id, '166: A patient on Olanzapine for 5 years develops tongue darting, lip smacking, and choreoathetoid movements of the fingers. Diagnosis?', '["Huntington''s", "Tardive Dyskinesia", "Akathisia", "Dystonia"]', 1, 'Chronic use side effect. (MGH Pocket)'),
    (v_topic_id, '167: First step in managing Tardive Dyskinesia?', '["Increase the antipsychotic dose", "Stop anticholinergics (if any), taper/switch offending antipsychotic (Clozapine is preferred), consider VMAT2 inhibitor", "Add Benztropine", "Add Levodopa"]', 1, 'Increasing the dose masks it temporarily but worsens it long-term. (Kaplan & Sadock)'),
    (v_topic_id, '168: How do VMAT2 inhibitors (Valbenazine, Deutetrabenazine) treat Tardive Dyskinesia?', '["They block dopamine receptors", "They deplete dopamine from presynaptic vesicles, reducing dopamine release", "They increase acetylcholine", "They block serotonin"]', 1, 'FDA approved specifically for TD. (First Aid)'),
    (v_topic_id, '169: A patient on Haloperidol develops a fever of 104F, severe muscle rigidity, tachycardia, sweating, and confusion. Labs show CK of 10,000. Diagnosis?', '["Malignant Hyperthermia", "Neuroleptic Malignant Syndrome (NMS)", "Serotonin Syndrome", "Catatonia"]', 1, 'Medical emergency. (MGH Pocket)'),
    (v_topic_id, '170: Which lab finding is highly characteristic of NMS?', '["Hypocalcemia", "Markedly elevated Creatine Kinase (CK) and Leukocytosis", "Elevated Troponin", "Hypokalemia"]', 1, 'Due to massive muscle breakdown (rhabdomyolysis) from rigidity. (Kaplan & Sadock)'),
    (v_topic_id, '171: Which medication can cause Malignant Hyperthermia (which looks identical to NMS)?', '["Haloperidol", "Inhaled anesthetics (Halothane) and Succinylcholine", "SSRIs", "Lithium"]', 1, 'NMS is from dopamine blockade; MH is from a ryanodine receptor genetic defect. Both treated with Dantrolene. (First Aid)'),
    (v_topic_id, '172: Antipsychotics are lipophilic and highly protein-bound. Can they be effectively removed by dialysis in an overdose?', '["Yes", "No", "Only atypicals", "Only typicals"]', 1, 'Dialysis is generally ineffective for antipsychotic overdose. (MGH Pocket)'),
    (v_topic_id, '173: A patient on Clozapine presents with a sore throat, fever, and chills. What must you do IMMEDIATELY?', '["Give antibiotics and observe", "Stop Clozapine and check a STAT CBC to rule out agranulocytosis", "Add acetaminophen", "Increase Clozapine"]', 1, 'Neutropenic fever is a medical emergency. (Kaplan & Sadock)'),
    (v_topic_id, '174: At what Absolute Neutrophil Count (ANC) must Clozapine be permanently discontinued?', '["< 1500", "< 1000", "< 500 / microL", "< 100"]', 2, 'Severe neutropenia (Agranulocytosis) = ANC < 500. (First Aid)'),
    (v_topic_id, '175: What cardiac issue requires monitoring during the first month of Clozapine therapy?', '["Endocarditis", "Myocarditis (look for unexplained fatigue, fever, tachycardia, elevated troponin)", "Pericarditis", "Aortic dissection"]', 1, 'Potentially fatal. (MGH Pocket)'),
    (v_topic_id, '176: Clozapine causes profound sialorrhea (drooling). How is this treated?', '["Increase Clozapine", "Alpha-2 agonists (clonidine) or anticholinergics (atropine drops sublingually)", "Beta blockers", "Stop Clozapine immediately"]', 1, 'A paradoxical effect since clozapine is highly anticholinergic elsewhere. (Kaplan & Sadock)'),
    (v_topic_id, '177: Which antipsychotic lowers the seizure threshold the MOST?', '["Haloperidol", "Clozapine", "Aripiprazole", "Lurasidone"]', 1, 'Dose-dependent risk; often requires prophylactic anticonvulsants at high doses. (First Aid)'),
    (v_topic_id, '178: A patient takes an antipsychotic and complains of severe orthostatic hypotension and failure to ejaculate. Which receptor blockade causes this?', '["Dopamine D2", "Serotonin 5HT2A", "Alpha-1 Adrenergic", "Muscarinic M1"]', 2, 'Alpha-1 blockade causes vasodilation and ejaculatory dysfunction. (MGH Pocket)'),
    (v_topic_id, '179: A patient takes an antipsychotic and complains of dry mouth, blurry vision, constipation, and urinary retention. Which receptor blockade causes this?', '["Dopamine D2", "Histamine H1", "Muscarinic M1 (Anticholinergic)", "Alpha-1"]', 2, 'Classic anticholinergic side effects. (Kaplan & Sadock)'),
    (v_topic_id, '180: A patient takes an antipsychotic and complains of extreme sedation and weight gain. Which receptor blockade is primarily responsible?', '["Dopamine D2", "Histamine H1 and Serotonin 5HT2C", "Alpha-1", "Muscarinic M1"]', 1, 'H1 blockade causes sedation and stimulates appetite. (First Aid)'),

    -- SECTION 4: Advanced Scenarios and Review (181-320)
    (v_topic_id, '181: A patient believes they are dead and their organs are rotting. Diagnosis?', '["Capgras", "Cotard syndrome", "Fregoli", "Othello"]', 1, 'Nihilistic delusion. (MGH Pocket)'),
    (v_topic_id, '182: A patient believes their wife was replaced by an exact look-alike. Diagnosis?', '["Capgras syndrome", "Cotard", "Fregoli", "Erotomanic"]', 0, 'Misidentification. (Kaplan & Sadock)'),
    (v_topic_id, '183: A patient believes Will Smith is deeply in love with her. Diagnosis?', '["Grandiose delusion", "Erotomanic delusion (De Clerambault''s syndrome)", "Persecutory", "Somatic"]', 1, 'Often solitary delusion with no other psychosis. (First Aid)'),
    (v_topic_id, '184: A patient has Schizophrenia. Their spouse starts believing the CIA is watching them too. Diagnosis for the spouse?', '["Schizophrenia", "Folie a deux (Shared Psychotic Disorder)", "Bipolar", "Delirium"]', 1, 'Separate them to treat the spouse. (MGH Pocket)'),
    (v_topic_id, '185: Brief Psychotic Disorder duration limit?', '["1 month", "6 months", "1 week", "1 year"]', 0, 'Returns to normal function. (DSM-5)'),
    (v_topic_id, '186: Schizophreniform Disorder duration limit?', '["1 month", "6 months", "1 year", "No limit"]', 1, 'Between 1 and 6 months. (DSM-5)'),
    (v_topic_id, '187: Schizophrenia duration requirement?', '["< 1 month", "> 6 months (including prodromal/residual phases)", "> 1 year", "No limit"]', 1, 'Must have at least 1 month of active symptoms. (DSM-5)'),
    (v_topic_id, '188: Schizoaffective Disorder key criterion?', '["Delusions/hallucinations for 2+ weeks WITHOUT mood symptoms", "Mood symptoms without psychosis", "Only mood symptoms", "None"]', 0, 'Proves psychosis is independent. (DSM-5)'),
    (v_topic_id, '189: Delusional Disorder key criterion?', '["At least 1 month of delusions, but NO prominent hallucinations or disorganized behavior", "Requires hallucinations", "Impaired daily function", "None"]', 0, 'Function is preserved. (DSM-5)'),
    (v_topic_id, '190: Major Depressive Disorder with Psychotic Features key criterion?', '["Psychosis occurs ONLY during the depressive episode", "Psychosis occurs without depression", "None", "None"]', 0, 'Psychosis is secondary. (DSM-5)'),
    (v_topic_id, '191: Best predictor of functional outcome in Schizophrenia?', '["Severity of hallucinations", "Severity of cognitive deficits and negative symptoms", "Severity of delusions", "None"]', 1, 'Cognitive deficits impair work/social life the most. (Kaplan & Sadock)'),
    (v_topic_id, '192: A 22-year-old male presents with first-break psychosis. What is the standard initial workup?', '["MRI only", "Urine toxicology, CBC, CMP, TSH, Syphilis/HIV screen, and sometimes neuroimaging", "EEG only", "None"]', 1, 'Rule out medical/substance causes first. (First Aid)'),
    (v_topic_id, '193: The "Dopamine Hypothesis" is supported by the fact that:', '["Cocaine/Amphetamines (dopamine agonists) cause psychosis", "Antipsychotics block D2", "Both A and B", "None"]', 2, 'Pharmacological evidence. (MGH Pocket)'),
    (v_topic_id, '194: The "Glutamate Hypothesis" is supported by the fact that:', '["PCP/Ketamine (NMDA antagonists) cause positive AND negative symptoms", "Serotonin causes sleep", "None", "None"]', 0, 'Explains negative symptoms better than dopamine. (Kaplan & Sadock)'),
    (v_topic_id, '195: A patient with Schizophrenia points to a chair and says "That is a sit-upon-it-rest-thing." This is an example of:', '["Neologism", "Echolalia", "Clang association", "Alogia"]', 0, 'Invented word. (First Aid)'),
    (v_topic_id, '196: A patient with Schizophrenia speaks, but the words have no logical connection: "Dog car blue tomorrow fast." This is:', '["Loose association", "Word salad (Incoherence)", "Tangentiality", "Thought blocking"]', 1, 'Severe disorganization. (MGH Pocket)'),
    (v_topic_id, '197: High-potency typicals (Haloperidol) bind D2 receptors very tightly. This leads to:', '["High sedation", "High EPS", "Low EPS", "High anticholinergic"]', 1, 'Tight binding = strong blockade = EPS. (Kaplan & Sadock)'),
    (v_topic_id, '198: Low-potency typicals (Chlorpromazine) bind D2 loosely but bind many other receptors. This leads to:', '["Low EPS, High sedation/anticholinergic/hypotension", "High EPS", "No side effects", "None"]', 0, 'Messy receptor profile. (First Aid)'),
    (v_topic_id, '199: Olanzapine is highly effective but causes massive:', '["Hair loss", "Weight gain and metabolic syndrome", "EPS", "Agranulocytosis"]', 1, 'Requires monitoring BMI, Lipids, A1c. (MGH Pocket)'),
    (v_topic_id, '200: Aripiprazole is unique because it is a:', '["D2 full antagonist", "D2 partial agonist", "Serotonin full agonist", "MAOI"]', 1, 'Can cause akathisia, but weight neutral. (Kaplan & Sadock)'),
    (v_topic_id, '201: Ziprasidone must be taken with food and monitored for:', '["QTc prolongation", "Agranulocytosis", "Liver failure", "Corneal deposits"]', 0, 'Do ECG before starting. (First Aid)'),
    (v_topic_id, '202: Lurasidone must be taken with food and is FDA approved for:', '["Bipolar depression and Schizophrenia", "OCD", "ADHD", "None"]', 0, 'Weight neutral, safe in pregnancy (Cat B). (MGH Pocket)'),
    (v_topic_id, '203: Clozapine is indicated for:', '["First-episode psychosis", "Treatment-resistant schizophrenia (failed 2 adequate trials) or Schizophrenia with severe suicidality", "Mild depression", "None"]', 1, 'The "last resort" that works best. (Kaplan & Sadock)'),
    (v_topic_id, '204: A patient on an antipsychotic gets a painful neck spasm (Torticollis) within 24 hours. Diagnosis?', '["Akathisia", "Acute Dystonia", "Tardive Dyskinesia", "Parkinsonism"]', 1, 'Give Benztropine IM. (First Aid)'),
    (v_topic_id, '205: A patient on an antipsychotic for 3 weeks complains of extreme restlessness and pacing. Diagnosis?', '["Akathisia", "Dystonia", "TD", "Anxiety"]', 0, 'Give Propranolol. (MGH Pocket)'),
    (v_topic_id, '206: A patient on an antipsychotic for 2 months develops a resting tremor, bradykinesia, and rigidity. Diagnosis?', '["Akathisia", "Parkinsonism", "TD", "NMS"]', 1, 'Give Benztropine or Amantadine. (Kaplan & Sadock)'),
    (v_topic_id, '207: A patient on an antipsychotic for 5 years develops lip smacking and tongue darting. Diagnosis?', '["TD", "Parkinsonism", "Akathisia", "Dystonia"]', 0, 'Taper drug, consider VMAT2 inhibitor (Valbenazine). (First Aid)'),
    (v_topic_id, '208: NMS triad?', '["Rigidity, Fever, Autonomic instability (plus elevated CK/WBC)", "Hyperreflexia, Fever, Tremor", "None", "None"]', 0, 'Life threatening. (MGH Pocket)'),
    (v_topic_id, '209: Serotonin Syndrome triad?', '["Rigidity, Fever", "Hyperreflexia/Clonus, Autonomic instability, Altered mental status", "None", "None"]', 1, 'Requires serotonergic agents. (Kaplan & Sadock)'),
    (v_topic_id, '210: Antipsychotic use in elderly with dementia?', '["Safe", "Black box warning for increased mortality", "Required by law", "None"]', 1, 'Use only for severe agitation/psychosis. (First Aid)'),
    (v_topic_id, '211: Tuberoinfundibular pathway dopamine blockade causes:', '["Amenorrhea, galactorrhea, gynecomastia, sexual dysfunction", "EPS", "Hallucinations", "None"]', 0, 'Prolactin rises. (MGH Pocket)'),
    (v_topic_id, '212: Nigrostriatal pathway dopamine blockade causes:', '["Prolactin rise", "EPS and Tardive Dyskinesia", "Relief of psychosis", "None"]', 1, 'Movement disorders. (Kaplan & Sadock)'),
    (v_topic_id, '213: Mesolimbic pathway dopamine blockade causes:', '["Relief of POSITIVE symptoms (hallucinations/delusions)", "EPS", "Prolactin rise", "None"]', 0, 'The therapeutic target. (First Aid)'),
    (v_topic_id, '214: Mesocortical pathway dopamine deficit causes:', '["Positive symptoms", "NEGATIVE symptoms and cognitive deficits", "EPS", "None"]', 1, 'Antipsychotics can worsen this. (MGH Pocket)'),
    (v_topic_id, '215: Schizoid PD vs Schizotypal PD vs Schizophrenia?', '["Schizoid = loner; Schizotypal = eccentric/magical thinking; Schizophrenia = full psychosis", "No difference", "None", "None"]', 0, 'The schizophrenia spectrum. (Kaplan & Sadock)'),
    (v_topic_id, '216: Which is a good prognostic factor for Schizophrenia?', '["Early onset", "Female gender", "Prominent negative symptoms", "None"]', 1, 'Women tend to have better outcomes. (First Aid)'),
    (v_topic_id, '217: Which is a poor prognostic factor for Schizophrenia?', '["Acute onset", "Presence of mood symptoms", "Male gender, insidious onset, poor premorbid function", "None"]', 2, 'Chronic deteriorating course. (MGH Pocket)'),
    (v_topic_id, '218: Catatonia treatment first-line?', '["Haloperidol", "Lorazepam (Benzos)", "Lithium", "None"]', 1, 'And ECT if refractory. (Kaplan & Sadock)'),
    (v_topic_id, '219: Visual hallucinations should make you think of:', '["Schizophrenia", "Medical illness, delirium, or substance intoxication", "Depression", "None"]', 1, 'Always do a full medical workup. (First Aid)'),
    (v_topic_id, '220: Olfactory hallucinations (e.g., smell of burning rubber) are classically associated with:', '["Temporal lobe epilepsy", "Schizophrenia", "Bipolar", "None"]', 0, 'An aura for complex partial seizures. (MGH Pocket)'),
    (v_topic_id, '221: Tactile hallucinations (e.g., bugs crawling) are classically associated with:', '["Alcohol withdrawal, Cocaine/Meth intoxication", "Schizophrenia", "Depression", "None"]', 0, 'Formication. (Kaplan & Sadock)'),
    (v_topic_id, '222: Command auditory hallucinations are:', '["Voices telling the patient to do something (e.g., hurt themselves or others)", "Voices conversing", "None", "None"]', 0, 'High risk for suicide/violence; psychiatric emergency. (First Aid)'),
    (v_topic_id, '223: Hypnagogic hallucinations occur:', '["While waking up", "While going to sleep", "During the day", "None"]', 1, 'Normal phenomenon, associated with narcolepsy. (MGH Pocket)'),
    (v_topic_id, '224: Hypnopompic hallucinations occur:', '["While going to sleep", "While waking up", "None", "None"]', 1, 'Also normal/narcolepsy. "Pompous upon waking". (Kaplan & Sadock)'),
    (v_topic_id, '225: Illusion vs Hallucination?', '["Illusion has a real external stimulus; Hallucination does not", "Opposite", "None", "None"]', 0, 'Definition. (First Aid)'),
    (v_topic_id, '226: Most common type of delusion in Schizophrenia?', '["Grandiose", "Persecutory", "Somatic", "None"]', 1, 'The FBI/CIA/neighbors are out to get them. (MGH Pocket)'),
    (v_topic_id, '227: Ideas of reference?', '["Believing the TV/Radio is speaking directly to you with special meaning", "Believing you are dead", "None", "None"]', 0, 'Common early symptom. (Kaplan & Sadock)'),
    (v_topic_id, '228: Thought broadcasting?', '["Thoughts can be heard by others", "Thoughts are stolen", "None", "None"]', 0, 'First-rank symptom. (First Aid)'),
    (v_topic_id, '229: Thought insertion?', '["Outside thoughts are placed into mind", "Thoughts are stolen", "None", "None"]', 0, 'First-rank symptom. (MGH Pocket)'),
    (v_topic_id, '230: Thought withdrawal?', '["Thoughts are taken out of mind by an outside force", "Thoughts are broadcast", "None", "None"]', 0, 'First-rank symptom. (Kaplan & Sadock)'),
    (v_topic_id, '231: Delusion of control?', '["Belief that outside forces are controlling one''s body or actions", "Belief that one is God", "None", "None"]', 0, 'Passivity phenomenon. (First Aid)'),
    (v_topic_id, '232: Alogia?', '["Poverty of speech", "Lack of motivation", "None", "None"]', 0, 'Negative symptom. (MGH Pocket)'),
    (v_topic_id, '233: Avolition?', '["Poverty of speech", "Lack of motivation / drive", "None", "None"]', 1, 'Negative symptom. (Kaplan & Sadock)'),
    (v_topic_id, '234: Anhedonia?', '["Lack of emotion", "Inability to experience pleasure", "None", "None"]', 1, 'Negative symptom. (First Aid)'),
    (v_topic_id, '235: Affective flattening?', '["No facial expressions, poor eye contact, monotonous voice", "Sadness", "None", "None"]', 0, 'Negative symptom. (MGH Pocket)'),
    (v_topic_id, '236: Disorganized behavior?', '["Wearing multiple winter coats in summer, bizarre posturing, public masturbation", "Crying", "None", "None"]', 0, 'Positive symptom. (Kaplan & Sadock)'),
    (v_topic_id, '237: Tangentiality vs Circumstantiality?', '["Circumstantiality eventually reaches the point; Tangentiality never does", "Opposite", "None", "None"]', 0, 'Thought process. (First Aid)'),
    (v_topic_id, '238: Loose associations (Derailment)?', '["Shifting between totally unrelated topics", "Rhyming", "None", "None"]', 0, 'Thought process. (MGH Pocket)'),
    (v_topic_id, '239: Word salad?', '["Random words with no grammar", "Rhyming", "None", "None"]', 0, 'Severe disorganization. (Kaplan & Sadock)'),
    (v_topic_id, '240: Clang associations?', '["Rhyming/punning without logical connection", "Made up words", "None", "None"]', 0, 'Often seen in mania too. (First Aid)'),
    (v_topic_id, '241: Neologisms?', '["Invented words", "Rhyming", "None", "None"]', 0, 'Thought process. (MGH Pocket)'),
    (v_topic_id, '242: Echolalia?', '["Repeating another''s words", "Repeating movements", "None", "None"]', 0, 'Catatonia sign. (Kaplan & Sadock)'),
    (v_topic_id, '243: Echopraxia?', '["Repeating another''s movements", "Repeating words", "None", "None"]', 0, 'Catatonia sign. (First Aid)'),
    (v_topic_id, '244: Waxy flexibility (Catalepsy)?', '["Maintaining postures placed by examiner", "Refusing to move", "None", "None"]', 0, 'Catatonia sign. (MGH Pocket)'),
    (v_topic_id, '245: Negativism?', '["Motiveless resistance to movement/instruction", "Saying no", "None", "None"]', 0, 'Catatonia sign. (Kaplan & Sadock)'),
    (v_topic_id, '246: Mutism?', '["Inability/refusal to speak", "Stuttering", "None", "None"]', 0, 'Catatonia sign. (First Aid)'),
    (v_topic_id, '247: Postpartum Psychosis?', '["Psychiatric emergency, often bipolar spectrum, high risk of infanticide", "Normal blues", "None", "None"]', 0, 'Needs hospitalization. (MGH Pocket)'),
    (v_topic_id, '248: Delusional Disorder somatic type vs Illness Anxiety Disorder?', '["Delusional disorder = fixed false belief (delusion); IAD = anxiety/fear but can be reassured", "No difference", "None", "None"]', 0, 'Degree of insight. (Kaplan & Sadock)'),
    (v_topic_id, '249: Body Dysmorphic Disorder with absent insight?', '["Classified as BDD, not delusional disorder", "Classified as Schizophrenia", "None", "None"]', 0, 'DSM-5 nuance. (First Aid)'),
    (v_topic_id, '250: Folie a deux treatment?', '["Separate the pair", "Give both ECT", "None", "None"]', 0, 'The submissive one often recovers. (MGH Pocket)'),
    (v_topic_id, '251: Schizophrenia suicide risk?', '["~5%", "0%", "50%", "None"]', 0, 'Elevated. (Kaplan & Sadock)'),
    (v_topic_id, '252: Schizophrenia life expectancy?', '["Reduced by 10-25 years (CVD, suicide, poor care)", "Normal", "None", "None"]', 0, 'High morbidity. (First Aid)'),
    (v_topic_id, '253: Schizophrenia and nicotine?', '["Up to 90% smoke; induces CYP1A2 (lowers olanzapine/clozapine levels)", "Low smoking rate", "None", "None"]', 0, 'Pharmacokinetic interaction! (MGH Pocket)'),
    (v_topic_id, '254: What happens to Clozapine levels if a patient suddenly quits smoking?', '["Levels rise (risk of toxicity/seizures)", "Levels fall", "No change", "None"]', 0, 'CYP1A2 induction stops. (Kaplan & Sadock)'),
    (v_topic_id, '255: First-line for Schizophrenia?', '["Second-generation (atypical) antipsychotic", "First-generation", "Clozapine", "None"]', 0, 'Better tolerability profile. (First Aid)'),
    (v_topic_id, '256: When to use Clozapine?', '["After failing 2 adequate trials of other antipsychotics", "First line", "None", "None"]', 0, 'Treatment resistance. (MGH Pocket)'),
    (v_topic_id, '257: Clozapine ANC monitoring?', '["Weekly x 6 months, biweekly x 6 months, then monthly", "Never", "None", "None"]', 0, 'REMS program. (Kaplan & Sadock)'),
    (v_topic_id, '258: Clozapine myocarditis?', '["Greatest risk in first month", "Late risk", "None", "None"]', 0, 'Monitor troponin/CRP. (First Aid)'),
    (v_topic_id, '259: Haloperidol decanoate?', '["Long-acting injectable, requires PO overlap", "Given IV", "None", "None"]', 0, 'Compliance aid. (MGH Pocket)'),
    (v_topic_id, '260: Paliperidone palmitate?', '["Long-acting injectable (Invega Sustenna), no PO overlap needed if loading dose given", "Given PO", "None", "None"]', 0, 'Modern LAI. (Kaplan & Sadock)'),
    (v_topic_id, '261: Acute Dystonia treatment?', '["Benztropine or Diphenhydramine IM", "Propranolol", "None", "None"]', 0, 'Fast relief. (First Aid)'),
    (v_topic_id, '262: Akathisia treatment?', '["Propranolol, Benztropine, or Clonazepam", "Levodopa", "None", "None"]', 0, 'Beta blocker first line. (MGH Pocket)'),
    (v_topic_id, '263: Parkinsonism treatment?', '["Benztropine or Amantadine", "Levodopa", "None", "None"]', 0, 'Anticholinergics. (Kaplan & Sadock)'),
    (v_topic_id, '264: Tardive Dyskinesia treatment?', '["Valbenazine (VMAT2 inhibitor), switch to Clozapine/Quetiapine", "Benztropine", "None", "None"]', 0, 'Anticholinergics worsen TD. (First Aid)'),
    (v_topic_id, '265: NMS treatment?', '["Dantrolene or Bromocriptine", "Benztropine", "None", "None"]', 0, 'Stop antipsychotic, cool patient. (MGH Pocket)'),
    (v_topic_id, '266: Quetiapine side effects?', '["Sedation, orthostasis, cataracts (in dogs, requires slit lamp in humans theoretically)", "EPS", "None", "None"]', 0, 'Very sedating. (Kaplan & Sadock)'),
    (v_topic_id, '267: Olanzapine side effects?', '["Weight gain, Diabetes, Dyslipidemia", "Agranulocytosis", "None", "None"]', 0, 'Metabolic monster. (First Aid)'),
    (v_topic_id, '268: Risperidone side effects?', '["Hyperprolactinemia, highest EPS of atypicals", "Weight neutral", "None", "None"]', 0, 'Acts like a typical at high dose. (MGH Pocket)'),
    (v_topic_id, '269: Ziprasidone side effects?', '["QTc prolongation", "Weight gain", "None", "None"]', 0, 'Must take with food. (Kaplan & Sadock)'),
    (v_topic_id, '270: Aripiprazole side effects?', '["Akathisia, impulse control disorders (gambling)", "Sedation", "None", "None"]', 0, 'Partial agonist. (First Aid)'),
    (v_topic_id, '271: Lurasidone side effects?', '["Akathisia, must take with food (350 kcal)", "Weight gain", "None", "None"]', 0, 'Safe in pregnancy. (MGH Pocket)'),
    (v_topic_id, '272: Chlorpromazine side effects?', '["Corneal deposits, blue-gray skin discoloration", "Retinal deposits", "None", "None"]', 0, 'Low potency typical. (Kaplan & Sadock)'),
    (v_topic_id, '273: Thioridazine side effects?', '["Retinitis pigmentosa, severe QTc prolongation", "Corneal deposits", "None", "None"]', 0, 'Low potency typical. (First Aid)'),
    (v_topic_id, '274: Pimozide side effect?', '["QTc prolongation (historic use for Tourette''s/Delusional disorder)", "Weight gain", "None", "None"]', 0, 'Typical antipsychotic. (MGH Pocket)'),
    (v_topic_id, '275: Typical antipsychotics vs Negative symptoms?', '["Do not improve them, may worsen them (Neuroleptic-induced deficit syndrome)", "Improves them", "None", "None"]', 0, 'Due to D2 blockade in cortex. (Kaplan & Sadock)'),
    (v_topic_id, '276: Atypical antipsychotics vs Negative symptoms?', '["May have slight benefit over typicals, but still largely ineffective", "Cures them", "None", "None"]', 0, 'Unmet medical need. (First Aid)'),
    (v_topic_id, '277: MRI finding in Schizophrenia?', '["Enlarged ventricles", "Small ventricles", "None", "None"]', 0, 'Cortical volume loss. (MGH Pocket)'),
    (v_topic_id, '278: Schizophrenia inheritance if both parents have it?', '["~40%", "100%", "10%", "None"]', 0, 'High genetic loading. (Kaplan & Sadock)'),
    (v_topic_id, '279: Synaptic pruning in Schizophrenia?', '["Excessive pruning during adolescence is theorized to cause onset", "No pruning", "None", "None"]', 0, 'Neurodevelopmental theory. (First Aid)'),
    (v_topic_id, '280: Prodromal phase features?', '["Social isolation, odd interests (magic, occult), poor hygiene", "Hallucinations", "None", "None"]', 0, 'Often precedes first break by months/years. (MGH Pocket)'),
    (v_topic_id, '281: Psychosis in ICU patient (Delirium) treatment?', '["Haloperidol (low dose IV/PO) or Quetiapine", "Benzos (can worsen delirium unless alcohol withdrawal)", "None", "None"]', 0, 'Avoid benzos in elderly delirium. (Kaplan & Sadock)'),
    (v_topic_id, '282: Anti-NMDA receptor encephalitis presentation?', '["Young female, ovarian teratoma, psychosis, chorea, dysautonomia", "Old male, tumor", "None", "None"]', 0, 'Autoimmune psychosis. (First Aid)'),
    (v_topic_id, '283: Neurosyphilis psychosis?', '["Argyll Robertson pupils (accommodate but don''t react to light)", "Blindness", "None", "None"]', 0, '"Prostitute''s pupil". (MGH Pocket)'),
    (v_topic_id, '284: Acute Intermittent Porphyria psychosis?', '["Abdominal pain, neuropathy, psychosis, red urine in light", "Chest pain", "None", "None"]', 0, 'Defect in heme synthesis. (Kaplan & Sadock)'),
    (v_topic_id, '285: Steroid-induced psychosis?', '["Dose-dependent, can cause mania or psychosis", "Safe", "None", "None"]', 0, 'Usually resolves upon taper. (First Aid)'),
    (v_topic_id, '286: Parkinson''s disease psychosis treatment?', '["Pimavanserin (5HT2A inverse agonist) or Quetiapine/Clozapine", "Haloperidol (will worsen Parkinson''s severely)", "None", "None"]', 0, 'Avoid D2 blockers! (MGH Pocket)'),
    (v_topic_id, '287: Lewy Body Dementia psychosis?', '["Visual hallucinations early in disease", "Auditory hallucinations", "None", "None"]', 0, 'Extreme sensitivity to antipsychotics (severe EPS). (Kaplan & Sadock)'),
    (v_topic_id, '288: Alzheimer''s psychosis?', '["Occurs late in disease", "Occurs first day", "None", "None"]', 0, 'Usually paranoia (e.g., "someone stole my purse"). (First Aid)'),
    (v_topic_id, '289: Delusion of guilt/sin?', '["Common in psychotic depression", "Common in Schizophrenia", "None", "None"]', 0, 'Mood-congruent. (MGH Pocket)'),
    (v_topic_id, '290: Delusion of poverty?', '["Common in psychotic depression", "Common in mania", "None", "None"]', 0, 'Mood-congruent. (Kaplan & Sadock)'),
    (v_topic_id, '291: Delusion of grandeur?', '["Common in mania", "Common in depression", "None", "None"]', 0, 'Mood-congruent. (First Aid)'),
    (v_topic_id, '292: Erotomania typically occurs in:', '["Women more than men", "Men more than women", "Children", "None"]', 0, 'Though men with it can be more violent/stalking. (MGH Pocket)'),
    (v_topic_id, '293: Othello syndrome (Jealousy) typically occurs in:', '["Men more than women", "Women more than men", "Equal", "None"]', 0, 'High risk of spousal homicide. (Kaplan & Sadock)'),
    (v_topic_id, '294: Delusion of parasitosis (Ekbom syndrome)?', '["Patient brings in a ''matchbox'' of lint/skin claiming it is bugs", "Patient thinks they are a bug", "None", "None"]', 0, 'Matchbox sign. (First Aid)'),
    (v_topic_id, '295: Olfactory reference syndrome?', '["Belief one emits a foul odor", "Belief others smell bad", "None", "None"]', 0, 'Similar to body dysmorphic disorder. (MGH Pocket)'),
    (v_topic_id, '296: Amok (Malaysia)?', '["Homicidal outburst", "Suicidal outburst", "None", "None"]', 0, 'Culture bound. (Kaplan & Sadock)'),
    (v_topic_id, '297: Koro (Asia)?', '["Fear of shrinking genitals", "Fear of growing genitals", "None", "None"]', 0, 'Culture bound. (First Aid)'),
    (v_topic_id, '298: Taijin Kyofusho (Japan)?', '["Fear of offending others", "Fear of being offended", "None", "None"]', 0, 'Culture bound. (MGH Pocket)'),
    (v_topic_id, '299: Dhat syndrome (India)?', '["Severe anxiety/hypochondriasis over loss of semen", "Loss of blood", "None", "None"]', 0, 'Culture bound. (Kaplan & Sadock)'),
    (v_topic_id, '300: Latah (Southeast Asia)?', '["Exaggerated startle response with echolalia/echopraxia", "Depression", "None", "None"]', 0, 'Culture bound. (First Aid)'),
    (v_topic_id, '301: Bizarre delusion example?', '["Aliens stole my brain without a scar", "My wife is cheating on me", "None", "None"]', 0, 'Physically impossible. (MGH Pocket)'),
    (v_topic_id, '302: Non-bizarre delusion example?', '["The police are watching me", "I am a werewolf", "None", "None"]', 0, 'Possible, but false. (Kaplan & Sadock)'),
    (v_topic_id, '303: Formal thought disorder?', '["Abnormality in the form/organization of thought (e.g., loose associations)", "Abnormality in content (delusions)", "None", "None"]', 0, 'How they think, not what they think. (First Aid)'),
    (v_topic_id, '304: Content of thought disorder?', '["Delusions, obsessions, suicidal ideation", "Loose associations", "None", "None"]', 0, 'What they are thinking about. (MGH Pocket)'),
    (v_topic_id, '305: Illusion?', '["Coat on a rack looks like a man", "Seeing a man where nothing is", "None", "None"]', 0, 'Misperception. (Kaplan & Sadock)'),
    (v_topic_id, '306: Hallucination?', '["Perception without a stimulus", "Misperception", "None", "None"]', 0, 'Requires awake/clear sensorium for psychiatric diagnosis. (First Aid)'),
    (v_topic_id, '307: Schizophrenia and IQ?', '["Often lower than average, with decline from premorbid baseline", "Higher than average", "None", "None"]', 0, 'Cognitive decline is typical. (MGH Pocket)'),
    (v_topic_id, '308: Double bind theory?', '["Old, discredited theory that conflicting parental messages cause Schizophrenia", "Genetic theory", "None", "None"]', 0, 'Historical footnote. (Kaplan & Sadock)'),
    (v_topic_id, '309: Schizophrenogenic mother?', '["Old, discredited psychoanalytic theory blaming the mother", "Genetic theory", "None", "None"]', 0, 'Historical footnote. (First Aid)'),
    (v_topic_id, '310: Expressed Emotion (EE)?', '["High EE families (critical, hostile, over-involved) increase relapse rates in Schizophrenia", "Low EE causes relapse", "None", "None"]', 0, 'Family therapy to lower EE prevents relapse. (MGH Pocket)'),
    (v_topic_id, '311: Assertive Community Treatment (ACT)?', '["Multidisciplinary team providing 24/7 care in the community to prevent hospitalization", "A type of therapy", "None", "None"]', 0, 'Highly effective for severe mental illness. (Kaplan & Sadock)'),
